@php
    $money = fn ($value): string => 'Rp '.number_format((int) $value, 0, ',', '.');
    $stockState = function ($product): array {
        if (! $product->product_type->tracksInventory()) return ['Tidak dilacak', 'bg-background text-muted'];
        $quantity = (int) ($product->inventory?->quantity ?? 0);
        if ($quantity <= 0) return ['Habis', 'bg-red-50 text-red-700'];
        if ($quantity <= (int) $product->minimum_stock) return ['Menipis', 'bg-amber-50 text-amber-700'];
        return ['Aman', 'bg-emerald-50 text-emerald-700'];
    };
@endphp
