    <section class="overflow-hidden rounded-lg border border-border bg-surface"><div class="overflow-x-auto"><table class="min-w-[960px] w-full text-left text-sm"><thead class="border-b border-border bg-background text-xs uppercase tracking-wide text-muted"><tr><th class="px-4 py-3">Produk</th><th class="px-4 py-3">Kategori</th><th class="px-4 py-3">SKU / Barcode</th><th class="px-4 py-3 text-right">Harga</th><th class="px-4 py-3 text-right">Stok</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Mutasi terakhir</th><th class="px-4 py-3"></th></tr></thead><tbody class="divide-y divide-border">@forelse($products as $product) @php([$state,$stateClass] = $stockState($product))<tr class="hover:bg-background"><td class="px-4 py-3"><a href="{{ route('manager.products.show', ['product' => $product->public_id]) }}" class="font-bold text-primary hover:underline">{{ $product->name }}</a><p class="mt-1 text-xs text-muted">{{ $product->is_active ? 'Aktif dijual' : 'Tidak aktif' }}</p></td><td class="px-4 py-3 text-secondary">{{ $product->category?->name ?? 'Tanpa kategori' }}</td><td class="px-4 py-3 text-xs text-muted">{{ $product->sku }}<br>{{ $product->barcode ?: '—' }}</td><td class="px-4 py-3 text-right font-semibold">{{ $money($product->selling_price) }}</td><td class="px-4 py-3 text-right font-bold">{{ $product->product_type->tracksInventory() ? number_format($product->inventory?->quantity ?? 0, 0, ',', '.') : '—' }}</td><td class="px-4 py-3"><span class="rounded-full px-2 py-1 text-xs font-bold {{ $stateClass }}">{{ $state }}</span></td><td class="px-4 py-3 text-xs text-muted">{{ $product->last_movement_at ? app(\App\Services\BrowserTimezone::class)->format($product->last_movement_at, 'd M Y · H:i') : '—' }}</td><td class="px-4 py-3 text-right"><a href="{{ route('manager.products.show', ['product' => $product->public_id]) }}" class="font-bold text-primary hover:underline">Lihat</a></td></tr>@empty<tr><td colspan="8" class="px-4 py-12 text-center text-muted">{{ $search || $category || $stockStatus ? 'Tidak ada produk yang cocok dengan filter.' : 'Belum ada produk pada store ini.' }}</td></tr>@endforelse</tbody></table></div><div class="border-t border-border px-4 py-3">{{ $products->links() }}</div></section>
